ProjectALife.DialogueShards["scenes_any_18"] = {
{"s2_c02_brass_button_031","any",2,"reg=family|tmp=seasoned|day=20,400|mood=warm",{1,"Josie lost her front tooth, it's under her pillow in a matchbox",2,"What's the tooth fairy got? There's no quarters that mean anything",1,"Cut the brass button off my church coat, it's shinier than a quarter",2,"She'll know",1,"She knows already, she's letting me have it"}},
{"s2_c02_lice_lard_032","any",3,"reg=family|tmp=seasoned|day=30,300|mood=funny",{1,"Lice, the kids have lice",2,"All of 'em?",3,"All of 'em, and I'm itching just standing here listening",1,"Mayonnaise on every head, a bread bag over it, and sleep in it - then we comb",2,"We don't have mayonnaise",1,"Then lard - Lord help us, it's lard"}},
{"s2_c02_ear_fever_033","any",2,"reg=family|tmp=seasoned|day=20,400|mood=fear",{1,"Ben's running a fever, a hundred and one",2,"Check him",1,"Checked him head to toe - twice - no marks, he keeps pulling at his left ear",2,"Ear infection - warm sock of salt against it, like your mama did",1,"I know it's his ear, I just needed you to be the one that said it"}},
{"s2_c02_nineteen_steps_034","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=26,36|mood=grim|world=door",{1,"A month today",2,"I quit wearing my watch last week, didn't notice for two days",1,"I notice everything, it's nineteen steps from my bed to that door in the dark",2,"Nineteen steps in the dark, huh... you've been in that dark too long"}},
{"s2_c02_mutter_roll_035","any",1,"reg=civilian,family|tmp=seasoned|day=30,400|hour=21,3|mood=sad",{1,"Mama - Daddy - Aunt Ruth - Travis",1,"Pastor Gene, both the Colliers - the mailman, whatever his first name was",1,"Every night, all of 'em, so nobody falls off the end"}},
{"s2_c02_mutter_gutters_036","any",1,"reg=civilian,family|tmp=seasoned|day=30,300|mood=sad|world=stairs",{1,"Gutters, that was his, gutters and the chimney and killing the spiders",1,"Did the gutters today, didn't fall off the ladder",1,"Still can't do the spiders"}},
{"s2_c02_tarp_in_rain_037","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=19,4|mood=sad|world=rain",{1,"Raining hard",2,"Mm",1,"I keep thinking about them out there getting wet - that's stupid",2,"I put the tarp over Jenny's before supper, didn't tell you, figured you'd think I was stupid"}},
{"s2_c02_one_shot_marine_038","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=grim|world=fence",{1,"Harold was a Marine, give him a salute at least",2,"Three volleys could bring trouble we don't need",3,"Then one shot - one",2,"Even one shot could leave us wishing we'd kept quiet",3,"Then we're up all night, he sat up plenty of nights for us"}},
{"s2_c02_pecan_stocking_039","any",2,"reg=family|tmp=seasoned|day=158,170|mood=sad",{1,"Do I hang Luke's stocking?",2,"Kids'll ask",1,"They'll ask either way",2,"Hang it, put a pecan in it, he always went for the pecans first"}},
{"s2_c02_three_peaches_040","any",3,"reg=civilian,family|tmp=seasoned|day=166,170|mood=funny|world=building",{1,"Merry Christmas, it's a can of peaches with a bow tied out of baling twine",2,"I got you a can of peaches",3,"Me too, off the same shelf - in the same cellar",1,"Well, now we all know what's for Christmas dinner"}},
{"s2_c02_electric_bill_041","any",2,"reg=civilian,family|tmp=seasoned|day=218,222|mood=funny",{1,"Happy Valentine's, I drew you a card on the back of the electric bill",2,"The last electric bill?",1,"July, eighty-one dollars and twelve cents - past due",2,"Most romantic thing anybody ever gave me, and now we'll never pay it"}},
{"s2_c02_four_eggs_easter_042","any",3,"reg=family|tmp=seasoned|day=265,272|mood=warm|world=fence",{1,"Easter, the hens gave us four eggs this week",2,"Hide 'em?",3,"If we hide 'em, somebody's got to find 'em - Grandpa found one in the gutter in June once",1,"Inside the fence only, and we count them back in before anybody eats anything"}},
{"s2_c02_dress_up_as_us_043","any",2,"reg=family|tmp=seasoned|day=110,115|mood=funny|world=door",{1,"Kids want to go trick-or-treating",2,"We go door to door every day of the week - tell 'em it's the same thing",1,"I told 'em, they want costumes",2,"Then they can dress up as us, muddy boots, a crowbar, and a bad attitude"}},
{"s2_c02_barn_door_names_044","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=sad|world=door",{1,"If we go to the farm at Echo Creek, we leave them here",2,"They're not here, they're in the ground - that's different",3,"It's not different to me",1,"Then we paint every name on the barn door before we go - big, so whoever comes after knows who's out back"}},
{"s2_c03_eyes_open_001","any",2,"reg=family|tmp=seasoned|day=20,400|hour=8,18|mood=calm",{1,"You're shutting your eyes before it goes off",2,"No I'm not",1,"You're shutting your eyes and turning your whole face away - that can's safe as a baby",2,"It's loud!",1,"It's loud for me too - eyes open, the can's not gonna shoot back"}},
{"s2_c03_pellet_pinecones_002","any",2,"reg=family|tmp=seasoned|day=20,400|mood=calm",{1,"No more real rounds for practice, pellet gun and pinecones",2,"That's a toy",1,"Knock twenty pinecones off the rail in a row with that toy and you get five real rounds",2,"Twenty in a row?",1,"Nineteen and you start over - go on"}},
{"s2_c03_amber_walked_off_003","any",3,"reg=family|tmp=seasoned|day=20,400|mood=angry|world=vehicle",{1,"Amber won't shoot, she laid the rifle down on the tailgate and walked off",2,"Then let her walk off",3,"She has to learn, it's not a hobby anymore",2,"She's the one who sat up with Mama at the end - she's done her share of hard things",3,"Hard things don't wait on anybody's schedule"}},
{"s2_c03_five_for_five_004","any",3,"reg=family|tmp=seasoned|day=30,400|mood=funny",{1,"Five for five, at fifty yards",2,"That's better than your daddy",3,"That's better than your daddy on a good day with his glasses on",1,"Can I tell him?",3,"Tell him at supper - loud, I want to watch his face"}},
{"s2_c03_whats_for_lunch_005","any",2,"reg=family|tmp=seasoned|day=20,400|hour=4,11|mood=grim|world=fence",{1,"Kyle got his first one this morning, at the fence - clean shot",2,"How's he doing?",1,"Threw up behind the shed, then asked what's for lunch",2,"That's about right, that's about how it went for me too"}},
{"s2_c03_walk_away_first_006","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|mood=calm",{1,"A gun's the last thing, a gun brings more of 'em, knife first, spear second, gun when you're about to die",2,"So I'm learning the knife?",1,"You're learning to walk away, knife is lesson two",2,"When do I get to the gun?",1,"When you're about to die, I just said"}},
{"s2_c03_count_out_loud_007","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|mood=calm",{1,"How many did you just fire?",2,"Um, four?",1,"Six - it's empty, you'd be standing there clicking at one of 'em",2,"Six - okay - I'll count",1,"Out loud, every time, till you don't have to"}},
{"s2_c03_wesley_list_008","any",2,"reg=family|tmp=seasoned|day=20,400|mood=sad",{1,"Wesley asked me would he have to shoot me if I got sick",2,"What did you tell that boy?",1,"Said no, said Granddad would",2,"And?",1,"And he said, but what if Granddad's sick too, that boy's been working on a list"}},
{"s2_c03_bore_bolt_oil_009","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|hour=16,21|mood=calm",{1,"Clean it before you eat, every time you shoot it",2,"I'm starving",1,"The rifle doesn't care if you're starving, bore, bolt, oil, wipe",2,"Bore, bolt, oil, wipe",1,"Get it done faster than that and I'll let you eat first next time"}},
{"s2_c03_slingshot_rabbit_010","any",2,"reg=family|tmp=seasoned|day=20,400|mood=funny",{1,"Tanner got a rabbit with his slingshot",2,"He did not",1,"Knocked it silly, I did the rest - but he'll be telling it his way for a year",2,"Let him, his way's better"}},
{"s2_c03_plywood_eyes_011","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=grim|world=fence",{1,"Painted a head on the plywood, just a circle with two eyes",2,"Why the eyes?",1,"So they get used to aiming at something that's looking back at 'em",3,"That's awful",1,"It is - help me set it up by the fence"}},
{"s2_c03_times_tables_012","any",3,"reg=family|tmp=seasoned|day=45,400|hour=8,12|mood=funny|world=building",{1,"School - kitchen table, times tables first",2,"Why do I need times tables? There's no stores",3,"Four people, three cans a day each - how many cans?",2,"Twelve, that ain't math - that's how much we're eating tonight",1,"It's both - nines - go"}},
{"s2_c03_history_books_013","any",2,"reg=family|tmp=seasoned|day=30,400|mood=warm",{1,"Rachel wants to know if this is gonna be in the history books",2,"Tell her yes",1,"She wants to know if we'll be in it, our actual names",2,"Tell her to write it down herself, then, that's how anybody ever got in one"}},
{"s2_c03_succotash_014","any",2,"reg=family|tmp=seasoned|day=30,400|mood=funny",{1,"Teaching Lucas to read off the can labels, he can spell succotash",2,"I can't spell succotash",1,"He hates it, that's why he learned it first, so nobody ever sneaks it past him"}},
{"s2_c03_water_duty_015","any",2,"reg=family|tmp=seasoned|day=60,400|mood=funny",{1,"Jess and the Hardin boy have pulled water duty together four days running",2,"Water duty's two buckets, it takes ten minutes",1,"It's been taking an hour",2,"Send her little brother along with them",1,"Did, he came back chewing a stick of gum",2,"Well, he's been bought"}},
{"s2_c03_fifteen_run_016","any",2,"reg=family|tmp=seasoned|day=30,400|mood=angry",{1,"I'm fifteen, I can go on the Rosewood run",2,"You can go when you can carry fifty pounds a mile and not talk the whole way",1,"I don't talk the whole way",2,"You've talked this whole time"}},
{"s2_c03_mutter_morning_list_017","any",1,"reg=civilian,family|tmp=seasoned|day=30,400|hour=5,8|mood=calm|world=fence",{1,"Water - hens - walk the fence - check the snares - fire",1,"Then breakfast, if the snares say so",1,"Snares said no yesterday - come on, snares, talk to me"}},
{"s2_c03_bottle_cap_checkers_018","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|hour=18,22|mood=funny",{1,"Checkers with bottle caps, red caps are cola, silver ones are root beer",2,"You got way more root beer caps than cola",3,"Because he drank all the root beer - back in August - alone, in the barn",1,"And now I'm winning at checkers, it all comes around"}},
{"s2_c03_volume_m_019","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=18,23|mood=funny|world=building",{1,"Only book in this house is the encyclopedia - volume M",2,"Where are you at?",1,"Mongoose, before that, Montana",2,"Anything in there about monsters?",1,"Couple of paragraphs, none of it's any help"}},
{"s2_c03_gate_rule_020","any",3,"reg=civilian,family|tmp=fresh,seasoned|day=20,90|mood=calm|world=fence",{1,"House rules, water before food, food before sleep - nobody goes past the fence alone",2,"That's it?",3,"And you don't leave the gate open - ever, not for one second",1,"The gate's the one that gets people, everything else, we'll forgive you for"}},
{"s2_c03_where_bathroom_021","any",3,"reg=civilian,family|tmp=seasoned|day=20,300|mood=funny|world=door,building",{1,"Where's the bathroom?",2,"Out back past the tomatoes - take the shotgun",1,"To the bathroom?",3,"To the bathroom, and knock before you open that door, folks have been surprised in there - both kinds of folks"}},
{"s2_c03_laughed_at_supper_022","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=20,120|mood=sad",{1,"Y'all laughed at supper, I didn't think people did that anymore",2,"We do it some",1,"How long before you could?",2,"Couple weeks, then Darla dropped the whole pot of beans in the dirt and we lost it - some of that was crying"}},
{"s2_c03_creek_man_vote_023","any",4,"reg=civilian,family|tmp=seasoned|day=20,400|mood=angry|world=water",{1,"Show of hands, the man at the creek stays one night - in the barn",2,"Yes",3,"No, he's got a pistol he won't turn loose of",4,"Yes, I wouldn't turn loose of mine either",1,"Two and two, so I say one night, in the barn, and the pistol sleeps in the house"}},
{"s2_c03_half_a_vote_024","any",3,"reg=family|tmp=seasoned|day=20,400|mood=funny",{1,"Does Callie get a vote?",2,"She's ten",3,"I do the hens every single morning, hens is a job",1,"Hens is a job, half a vote",3,"Which half?"}},
{"s2_c03_rooster_trade_025","any",2,"reg=family|tmp=seasoned|day=20,400|mood=funny|world=door",{1,"I'll take your outhouse week if you take my hens",2,"Outhouse is worse than hens",1,"The rooster hates me, he waits behind the coop door for me",2,"Deal, but I'm telling everybody at supper a rooster beat you"}},
{"s2_c03_rabbit_path_026","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm",{1,"Snare loop's the size of your hand, bottom of it a fist off the ground",2,"How do you know where to set it?",1,"Find the little path through the grass, rabbits go the same way every day, like people",2,"Like people used to"}},
{"s2_c03_creek_swim_027","any",3,"reg=family|tmp=seasoned|day=330,400|hour=12,18|mood=warm|world=water",{1,"Creek swim - twenty minutes, two on the bank with rifles, facing out",2,"Can I swim instead of guard?",3,"Everybody swims - everybody guards, you just don't do both at once",1,"In - go, before I change my mind about the whole thing"}},
{"s2_c03_yard_sale_deer_028","any",2,"reg=family|tmp=seasoned|day=40,400|mood=warm|world=building",{1,"Your daddy was a terrible shot - did you know that?",2,"He had all those deer heads on the wall",1,"He bought two of them at a yard sale in Brandenburg - made me swear on the Bible",2,"Then why are you telling me?",1,"Because you're already better than he ever was, and I'm done keeping that man's secrets"}},
{"s2_c03_heel_to_toe_029","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=funny|world=water",{1,"Heel down soft, roll to the toe, outside edge of your foot",2,"I feel like a cat",1,"You sound like a cow walking in a creek - again"}},
{"s2_c03_window_chair_030","any",2,"reg=family|tmp=seasoned|day=20,400|hour=0,5|mood=sad|world=window",{1,"Wren's up again - same dream, her Sunday school teacher at the window",2,"Mrs. Belcher?",1,"She wants me sitting in the window - so Mrs. Belcher sees me first and not her",2,"Go on in there, then, I'll bring the chair"}},
{"s2_c03_mutter_before_lesson_031","any",1,"reg=family|tmp=seasoned|day=20,400|mood=fear",{1,"I'll show her the safety, the sights... just don't let her see my hands shaking",1,"I taught her to ride a bike, it's the same thing - sort of the same thing",1,"It's nothing like a bike - okay - okay"}},
{"s2_c03_damp_jeans_032","any",2,"reg=civilian,family|tmp=seasoned|day=20,90|mood=funny",{1,"Wash day - Washboard's in the tub",2,"Jeans won't dry, it's too wet out - mine have hung on that line since Thursday",1,"Then wear 'em damp, everybody else is",2,"Damp jeans in August, I've got a rash in places I didn't know I had"}},
{"s2_c03_hickory_033","any",2,"reg=civilian,family|tmp=seasoned|day=90,260|mood=calm",{1,"Don't swing it like you're mad at it, let the weight drop",2,"I am mad at it",1,"Be mad at it later, aim for the crack",2,"It bounced",1,"It's hickory, hickory doesn't care how you feel - again"}},
{"s2_c03_june_song_034","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=17,23|mood=warm",{1,"What's that you keep humming?",2,"Don't know, something that was on the radio all June, can't get the words",1,"Hum it again - slower",2,"Why?",1,"Because I heard it all June too, and I'm about two notes from the words"}},
{"s2_c03_papaw_hoe_035","any",2,"reg=family|tmp=seasoned|day=330,400|hour=12,17|mood=funny",{1,"Papaw used to hoe the garden through the worst heat",2,"Said he'd done it since forty-eight",1,"He was thirty in forty-eight",2,"And said the weeds were the same age they always were. Wouldn't stop till somebody brought him water"}},
{"s2_c03_band_teacher_036","any",2,"reg=family|tmp=seasoned|day=20,400|mood=sad|world=fence",{1,"That one at the fence is Mr. Farris, he ran the band at school",2,"I know, baby",1,"He let me play the big drum at the Christmas concert - nobody else got to",2,"Then let me do this one, you go wash up"}},
{"s2_c03_micah_rules_037","any",2,"reg=family|tmp=seasoned|day=20,400|mood=funny",{1,"Heard Micah teaching his little sister the gun rules",2,"Good, which ones?",1,"Never point it at anything you don't want to eat",2,"That's close, honestly, that's close enough"}},
{"s2_c03_first_watch_jacket_038","any",2,"reg=family|tmp=seasoned|day=20,400|hour=4,9|mood=warm",{1,"Put Eli on watch with me last night - first time",2,"How'd he do?",1,"Counted stars over the barn out loud, asleep somewhere in the forties",2,"You let him sleep?",1,"Put my jacket on him and did his half, he'll tell everybody he made it to dawn - let him"}},
{"s2_c03_rabbit_knot_039","any",2,"reg=family|tmp=seasoned|day=20,400|mood=funny|world=trees",{1,"Rabbit comes up out of the hole, runs around the tree, goes back down the hole",2,"My rabbit went around the wrong tree",1,"Then your rabbit's gonna drop that tarp on your head in the first wind - again"}},
{"s2_c03_whistle_signals_040","any",2,"reg=family|tmp=seasoned|day=20,400|mood=funny|world=water",{1,"One long whistle, come home, two short, get down and hide, three, run for the creek",2,"What if I can't whistle?",1,"Then you're learning to whistle today, wet your lips",2,"I'm just spitting on myself"}},
{"s2_c03_single_shot_041","any",2,"reg=family|tmp=seasoned|day=30,400|mood=calm",{1,"Granddad's giving Jody the single-shot - the four-ten",2,"It only holds one shell",1,"He says that's the point, one shell and you learn to mean it",2,"Mean it, and then run - tell him to teach the running part too"}},
{"s2_c03_hairbrush_draw_042","any",2,"reg=family|tmp=seasoned|day=30,400|mood=warm|world=building",{1,"Caught Tyler in front of the bathroom mirror practicing a quick draw",2,"With a loaded gun?",1,"With a hairbrush, saying tough things at himself",2,"Let him have the hairbrush a while longer"}},
{"s2_c03_insurance_man_043","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=15,60|mood=calm|world=fence",{1,"Never fired a gun in my life, I sold insurance in Elizabethtown",2,"Then you know about risk, that's half of it",1,"What's the other half?",2,"Hitting what you meant to, we'll start on the fence post, it holds still"}},
{"s2_c03_curtain_patches_044","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny|world=window,building,road",{1,"Patched the knees on everybody's jeans, only cloth left was the kitchen curtains",2,"So we've all got strawberries on our knees",1,"Anybody sees us coming down the road, they'll think we're a gospel group",2,"We'd be a bad one"}},
{"s2_c03_route_six_045","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=calm|world=road",{1,"What'd you do before all this?",2,"Rural carrier, route six, twenty-two years",1,"Can you shoot?",2,"No, but I know every back road and every dog between here and Irvington - most of the dogs by name",3,"He's on the scouting runs - starting tomorrow"}},
{"s2_c03_pantry_door_rules_046","any",2,"reg=family|tmp=seasoned|day=30,400|mood=warm|world=door,building",{1,"Who wrote rules on the pantry door?",2,"Abby, in crayon - one, shut the gate, two, no crying at supper",1,"Rule two's gonna get broke",2,"Read rule three, rule two is only on Tuesdays"}},
{"s2_c04_among_them_001","any",3,"reg=civilian,family|tmp=seasoned|day=30,300|hour=7,18|mood=calm|world=road",{1,"Note nailed to the stop sign on Rosewood Road, eleven people at the Baptist youth camp, a doctor among them - come by daylight",2,"Or come by daylight and get robbed in the parking lot",3,"Who writes among them? Robbers don't write among them",2,"Smart robbers do",1,"We watch that camp from the ridge two whole days before anybody walks in"}},
{"s2_c04_three_chimneys_002","any",2,"reg=civilian,family|tmp=seasoned|day=120,260|hour=6,10|mood=calm",{1,"Three chimneys smoking over toward Echo Creek this morning",2,"Three houses? Or one bunch with three stoves?",1,"Can't tell from here, smoke's going straight up, they're not hiding a thing",2,"Either they're not scared of anybody, or they want folks to come",1,"Or both, neither one makes me want to go"}},
{"s2_c04_mule_senator_003","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"The man with the mule cart came back through, still trading salt for batteries",2,"He got a name?",3,"Says his name's whatever you want to call him",1,"So I call him the man with the mule cart",3,"He said that's fine, he said the mule's name is Senator, though, and to use it"}},
{"s2_c04_january_tomatoes_004","any",2,"reg=civilian,family|tmp=seasoned|day=90,400|mood=calm",{1,"Heard some women took over the greenhouse at the vocational school in March Ridge - tomatoes in January",2,"Says who?",1,"The mule man",2,"The mule man also saw a black bear inside a bank",1,"Well, I believe the tomatoes before I believe the bear"}},
{"s2_c04_fort_lights_005","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|hour=21,3|mood=fear|world=generator",{1,"Lights on at the Fort again, just a few - out past the ridge",2,"Army's still in there, then",3,"Somebody's in there with a generator, that doesn't make it the Army",1,"Doesn't make it not",3,"Close the curtain, whoever it is can see our lamp same as we see theirs"}},
{"s2_c04_white_x_006","any",2,"reg=civilian,family|tmp=seasoned|day=30,300|mood=fear|world=vehicle,door",{1,"Houses along Hayden Road got white X's painted on the doors - fresh paint",2,"Somebody clearing them?",1,"Somebody marking them, every house with an X had food in it, the rest are empty",2,"So they're coming back with a truck - check our door",1,"Ours is clean",2,"Check it again tomorrow"}},
{"s2_c04_middle_school_kids_007","any",2,"reg=civilian,family|tmp=seasoned|day=40,300|mood=sad",{1,"Somebody swears there's kids living in the middle school in Riverside - just kids - no grown-ups",2,"Living on what?",1,"The cafeteria, school stocked up for the fall term before any of it",2,"Then I'll go look",1,"They ran from the last grown-up who went to look"}},
{"s2_c04_houseboat_sheet_008","any",2,"reg=civilian,family|tmp=seasoned|day=30,300|hour=4,11|mood=calm|world=building,water",{1,"Houseboat went down the river this morning - slow, bedsheet flying off the roof",2,"Words on it?",1,"Something painted, too far to read it",2,"Could've said help, could've said stay back",1,"Probably said both, everybody's sign says both now"}},
{"s2_c04_riders_dusk_009","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|hour=16,22|mood=fear",{1,"Five people on horses crossed the Dixie Highway at dusk - rifles across the saddles",2,"Horses don't need gas",3,"Horses need hay, whoever they are, they got a barn and a field somewhere close",1,"And they're riding around at dusk looking at everybody else's"}},
{"s2_c04_flea_market_chain_010","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"Somebody's running a swap at the old flea market lot off 31W - every other Sunday",2,"Who keeps the peace?",3,"Church bunch from Brandenburg, nobody carries a gun past the chain across the entrance",2,"And the ones who don't listen about the chain?",3,"Heard it happened once, nobody's tried it twice",1,"I'll go look, I'm not bringing anything we can't stand to lose"}},
{"s2_c04_froze_standing_011","any",3,"reg=civilian,family|tmp=seasoned|day=178,235|mood=fear|world=fence",{1,"Man at the swap said they freeze solid in January - stand there like fence posts",2,"So we walk right past 'em",3,"Walked past a froze one in the Hobbs yard, it turned its head after me",1,"Its head?",3,"Slow as a clock hand... and I walked past FAST, believe me"}},
{"s2_c04_spring_line_012","any",2,"reg=civilian,family|tmp=seasoned|day=120,300|mood=sad",{1,"Heard the Army's lifting the line come spring, once the ground thaws",2,"Heard they were lifting it in September too",1,"I heard that one too",2,"And October, and by Thanksgiving, for sure",1,"I know, I just like how spring sounds when somebody says it"}},
{"s2_c04_stump_trade_013","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=warm|world=water",{1,"Left two jars of beans on the stump at the creek crossing - came back to a box of shotgun shells",2,"Same folks as last time?",1,"Never laid eyes on 'em - don't want to, it works fine like this",2,"Best neighbors we ever had"}},
{"s2_c04_whitaker_smoke_014","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|hour=6,11|mood=grim|world=door,fire",{1,"No smoke from the Whitaker place this morning",2,"Maybe they slept late",3,"They've had smoke going by six every morning since August",1,"We wait till noon, still nothing, two of us walk over",2,"And if it's still nothing when we get there?",1,"Then we take what they'd want us to take, and we shut the door on the way out"}},
{"s2_c04_grain_elevator_015","any",3,"reg=civilian,family|tmp=seasoned|day=20,200|mood=fear|world=vehicle",{1,"Heard the ones that broke out of the prison took over the grain elevator in Irvington",2,"That's a good ways off",3,"Not in a truck it isn't",1,"Then no more burning green wood, dry wood only, dry wood don't smoke"}},
{"s2_c04_rifle_for_coffee_016","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"Heard a man in West Point traded a deer rifle for one pound of coffee",2,"A whole rifle?",1,"Scope and all",2,"I'd have traded the rifle and thrown in the deer"}},
{"s2_c04_mutter_empty_can_017","any",1,"reg=civilian,family|tmp=seasoned|day=70,400|hour=5,9",{1,"Can's been empty since September, still got the smell down in it",1,"Lid off, one good breath - lid back on",1,"Morning"}},
{"s2_c04_freezer_aisle_018","any",2,"reg=civilian,family|tmp=seasoned|day=15,80|hour=11,19|mood=funny|world=door,water",{1,"You know where I'd go right now if I could go anywhere? The frozen food aisle",2,"Not the beach? Not your mama's?",1,"Open the freezer door and stand there with my shirt untucked till the manager comes",2,"Manager's not coming - go stand in the creek"}},
{"s2_c04_worst_part_heat_019","any",3,"reg=civilian,family|tmp=seasoned|day=15,70|hour=12,18|mood=funny",{1,"Worst thing about no air conditioning - go",2,"Sleeping",3,"Sweating through the only shirt I got left",1,"The smell of you two"}},
{"s2_c04_dog_gets_middle_020","any",3,"reg=civilian,family|tmp=seasoned|day=180,240|hour=19,23|mood=calm|world=building",{1,"Everybody in the front room tonight, one stove, one room",2,"Dog too?",3,"Dog's the best heater we got, dog gets the middle",2,"Dog got the middle last night",3,"And you were warm, weren't you"}},
{"s2_c04_frost_drawing_021","any",2,"reg=family|tmp=seasoned|day=180,235|hour=6,10|mood=warm|world=window,snow",{1,"Kids drew in the frost on the window, a house and a dog and a sun",2,"Which house?",1,"Ours, the old one, it's got the swing set",2,"Leave it, don't wipe it - let it melt off on its own"}},
{"s2_c04_last_row_wood_022","any",2,"reg=civilian,family|tmp=seasoned|day=195,240|mood=grim",{1,"Woodpile's down to the last row",2,"February's still got three weeks in it",1,"Then the piano goes",2,"Don't you say that where Mom can hear it",1,"She's the one that said it"}},
{"s2_c04_windows_open_023","any",2,"reg=civilian,family|tmp=seasoned|day=258,300|mood=calm|world=window,stairs",{1,"Warm enough to open the windows - first day",2,"House smells like five months of us",1,"Beat the rugs, air the quilts, and burn whatever that is under the stairs",2,"That's Lyle's other boot",1,"Burn it anyway"}},
{"s2_c04_green_sky_024","any",3,"reg=civilian,family|tmp=seasoned|day=260,340|hour=13,21|mood=fear|world=door,building,wind",{1,"Sky's gone green, that's tornado green",2,"Cellar - everybody - grab the lantern",3,"There's two of them standing right by the cellar doors",1,"Then we go down through the kitchen hatch - now, the wind'll take care of those two, or it won't"}},
{"s2_c04_hail_lettuce_025","any",2,"reg=civilian,family|tmp=seasoned|day=270,340|mood=angry",{1,"Hail, size of peas - Shredded the lettuce and every one of the young tomatoes",2,"Bean rows?",1,"Beans made it, beans always make it - I am sick to death of beans",2,"Be sick of 'em and fed, then, help me stake what's left"}},
{"s2_c04_rosewood_bell_026","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"Church bell rang over in Rosewood Sunday - twelve times",2,"Somebody's still keeping Sunday",1,"Or somebody's pulling every one of them in town over to that church on purpose",2,"Why would anybody do that?",1,"So they can have the rest of the town to themselves for an afternoon"}},
{"s2_c04_bridge_bribe_027","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"Fella at the swap swears the bridge at West Point opens one night a month - guards take a bribe",2,"What kind of bribe?",1,"He didn't know, he hadn't been",3,"So a man who never crossed a bridge told you how to cross it",1,"When you say it like that, sure"}},
{"s2_c04_okra_squash_028","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm|world=fence",{1,"Two of the Echo Creek bunch came by the fence - a man and a girl - hands empty",2,"What'd they want?",1,"To swap seed, they got okra - we got squash",3,"Nobody wants okra",1,"The girl said the exact same thing about our squash - I liked her"}},
{"s2_c04_hearing_aid_029","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|hour=16,5|mood=angry|world=fence",{1,"That bunch out of {den} hit the Coopers last night - took the goats",2,"Both goats?",3,"And Mr. Cooper's hearing aid, pulled it right out of his ear",1,"What does anybody want with a hearing aid?",3,"The battery",2,"Two on the fence tonight, every night, till we say different"}},
{"s2_c04_red_cross_paint_030","any",2,"reg=civilian,family|tmp=seasoned|day=40,300|mood=fear",{1,"Somebody painted a red cross on the side of the Ekron feed store",2,"Real doctor?",1,"Or somebody wants hurt folks to walk in on their own - hurt folks carry medicine",2,"I wish you hadn't said that, I was halfway to packing a bag"}},
{"s2_c04_phone_cord_dream_031","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|hour=5,10|mood=funny|world=building",{1,"Dreamed the phone rang, the kitchen one, with the long curly cord",2,"Who was it?",1,"Never found out, I was still untangling the cord",2,"That's the most honest dream I ever heard"}},
{"s2_c04_yeast_rolls_032","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|hour=17,22|mood=funny|world=road",{1,"First thing I eat when this is over, pizza from the place next to the bowling alley in Muldraugh",2,"That place closed in eighty-nine",1,"It's my dream, it's open in my dream",3,"Then I want the yeast rolls from the steakhouse on Dixie - the basket they bring before you order",2,"Y'all are making it worse - eat your squirrel"}},
{"s2_c04_winter_list_033","any",3,"reg=civilian,family|tmp=seasoned|day=60,110|mood=calm|world=vehicle,building",{1,"Winter list's long - wood, lamp oil, a second stove, and the cellar dug out deeper",2,"A second stove from where?",3,"Methodist parsonage has a potbelly in the fellowship room",1,"Parsonage, then - bring the dolly and four strong backs, those things weigh like a car"}},
{"s2_c04_farm_or_house_034","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm|world=building",{1,"Would you rather try a farm or stay in a house? I keep thinking about Echo Creek",2,"Depends on who else was there",3,"Fields might give us a longer view, if we found a place with open ground",4,"And could leave us easier to spot. A long view works both ways",1,"Then we'd have to look properly before voting on anything. Not decide over an argument at supper"}},
{"s2_c04_crider_hay_035","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm|world=door,building",{1,"I once walked the ridge to the Crider place. Saw hay and a wagon in the barn",2,"Had anybody been through?",1,"Cans stacked neat on the porch, door pulled shut. Looked that way",2,"Then I wouldn't have called it empty just because nobody answered",1,"No. Having somewhere to take the hay didn't make it ours"}},
{"s2_c04_stale_gas_036","any",2,"reg=civilian,family|tmp=seasoned|day=150,400|mood=grim|world=vehicle,spring",{1,"Truck's running rough, gas is going stale in the tank",2,"How long's gas good for?",1,"Six months, a year if you're lucky - every tank in the county's on that same clock",2,"Then this spring we learn to walk everywhere, or we learn to ride the goat"}},
{"s2_c04_plus_some_037","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"Echo Creek bunch asked what we call ourselves",2,"We don't call ourselves anything",3,"They call themselves the Creek, like a softball team",1,"I told 'em we're the Hendersons - plus some",2,"The Hendersons plus some, I like that - that's us"}},
{"s2_c04_november_rotor_038","any",3,"reg=civilian,family|tmp=seasoned|day=100,400|mood=fear",{1,"Helicopter, I heard it, out over Brandenburg",2,"There hasn't been a helicopter since August",3,"I heard it too, real low, then gone",1,"Nobody runs out waving, we find out where it set down and who got out before anybody waves at anything"}},
{"s2_c04_steno_pad_039","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"Lady at the swap trades honey, wouldn't take my shells, she wanted news",2,"News?",1,"Who's alive in March Ridge, who we've seen - names, mostly",2,"And you gave her some?",1,"Every name I had, she wrote them in a steno pad, gave me two jars, and said come back with more"}},
{"s2_c04_mutter_believe_pony_040","any",1,"reg=civilian,family|tmp=seasoned|day=60,400|mood=funny",{1,"Army's coming in the spring - Army's gone, there's a cure at the Fort - there's no Fort",1,"Somebody's got a boat, somebody's got a plane - somebody over in Ekron's got a pony",1,"I believe the pony, everything else, I'll see it first"}},
{"s2_c04_four_pots_041","any",2,"reg=civilian,family|tmp=seasoned|day=180,245|hour=17,22|mood=warm|world=fence,building",{1,"Heated four pots on the stove, you're getting a hot bath",2,"Me? What about everybody else?",1,"Everybody else voted while you were out on the fence three nights running - get in",2,"I don't know what to say",1,"Say nothing, water goes on the garden after, so don't dawdle"}},
{"s2_c04_creek_gate_sheet_042","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"Heard the Creek bunch makes everybody strip down at their gate - kids, old folks, everybody",2,"In front of people?",3,"Behind a bedsheet on a clothesline, one of their women checks the women",2,"Well, that's more manners than I expected out of anybody",1,"That's more checking than we do... maybe I'll hang us a sheet"}},
{"s2_c05_butter_pecan_001","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=sad|world=vehicle,water,road",{1,"Route to the Rosewood hardware, up the creek bed, over the tracks, in the back by the loading dock",2,"Carol and me used to get ice cream right across the street from that hardware",3,"Not now",1,"Loading dock, two go in, one stays with the truck, one watches the tracks",2,"Butter pecan, she got butter pecan every single time",1,"You're on the truck"}},
{"s2_c05_west_culvert_002","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|mood=sad|world=fence",{1,"You eat anything today?",2,"Fence needs looking at on the west side",1,"I asked about you, not the fence",2,"West side, down by the culvert",1,"I'll leave a plate on the step"}},
{"s2_c05_since_tuesday_003","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=15,40|mood=sad",{1,"I haven't cried since Tuesday",2,"Well, that's something",1,"Is it? Feels like something broke off in there and I didn't hear it go",2,"I don't know what it is, I just know I stopped around the same week you did"}},
{"s2_c05_bag_by_door_flashlight_004","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=20,45|hour=16,5|mood=calm|world=cars,door",{1,"You still keep your bag packed by the door?",2,"For when the trucks come",1,"Could I borrow the flashlight out of it? Just for tonight",2,"It stays in the bag",1,"Okay, I'll ask you again next week"}},
{"s2_c05_cross_the_road_005","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|mood=funny|world=road",{1,"Why'd the zombie cross the road?",2,"Don't",3,"Why?",1,"Because we were on the other side of it",3,"Oh",2,"I told you don't"}},
{"s2_c05_same_silo_006","any",3,"reg=civilian,family|tmp=seasoned|day=20,400|hour=4,11|mood=funny",{1,"We're not lost",2,"We have passed that silo twice",1,"That's a different silo - same kind",3,"It's got the same hole in it you put there this morning shooting at a crow"}},
{"s2_c05_ugly_coats_007","any",3,"reg=civilian,family|tmp=seasoned|day=80,150|mood=calm",{1,"Thrift store in Muldraugh - coats, I got everybody's size on a list in my pocket",2,"Kids'll grow out of 'em by spring",1,"Then the kids get the big ones and we roll the sleeves",3,"Grab the ugly ones first, nobody ever went back to loot an ugly coat"}},
{"s2_c05_under_the_redbud_008","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=sad",{1,"Bill's gone, in the night, in his sleep, his heart, I think - not them",2,"Not them?",1,"I sat with him an hour to be sure, he stayed Bill the whole hour",2,"Then he gets the spot under the redbud, he always did like the redbud"}},
{"s2_c05_little_pitchers_009","any",4,"reg=family|tmp=seasoned|day=20,400|mood=grim",{1,"Heard the Dotsons took in a man that turned the second night",2,"Heard it was the third night",3,"Little pitchers",4,"What's a little pitcher?",3,"You are - go check the hens"}},
{"s2_c05_five_more_minutes_010","any",2,"reg=civilian,family|tmp=seasoned|day=20,400|hour=17,21|mood=sad|world=building,road",{1,"Supper's ready",1,"Beans and the rest of the rabbit, I kept it warm on the back of the stove",1,"That road's not gonna do anything different if you look away for twenty minutes",2,"I know it, five more minutes"}},
{"s2_c05_hornworm_011","any",2,"reg=family|tmp=seasoned|day=30,90|mood=funny",{1,"There's a big green worm on the tomatoes! It's got a horn!",2,"Hornworm - pick it off and give it to the hens",1,"It's looking at me",2,"The hens are gonna look right back at it"}},
{"s2_c05_february_whistle_012","any",3,"reg=civilian,family|tmp=seasoned|day=205,235|mood=angry",{1,"You whistle that one more time",2,"What? It's February - what else am I supposed to do?",3,"Split wood, whistle out there",2,"It's nine degrees out there",1,"Then whistle faster"}},
{"s2_c05_seed_corn_rope_013","any",3,"reg=civilian,family|tmp=seasoned|day=90,400|mood=grim",{1,"Swap folks say the Brandenburg church bunch hanged a man for stealing",2,"Stealing what?",1,"Seed corn",3,"Seed corn's next year, that's stealing next year off forty people",2,"He's still a man",3,"I never said he wasn't"}},
{"s2_c05_bank_lobby_014","any",2,"reg=civilian,family|tmp=seasoned|day=15,80|hour=11,18|mood=funny|world=door",{1,"I used to walk in the bank on Main just to stand in the lobby - didn't even have an account there",2,"They let you?",1,"Teller asked was I making a deposit, I said yes ma'am, I'm depositing myself",2,"Well, bank's still there, door's off the hinges - go on and make a withdrawal"}},
{"s2_c05_three_in_a_hill_015","any",4,"reg=civilian,family|tmp=seasoned|day=280,330|mood=funny",{1,"Corn goes in first, knee high, you plant beans at the foot, squash in between",2,"Why all three in one hill?",3,"Beans climb the corn, squash leaves shade out the weeds",4,"And the coons eat all three at once - real efficient",1,"That's what the dog's for",4,"There's no dog, Ray",1,"That's what the dog would be for"}},
{"s2_c05_forgot_the_radio_016","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=20,60|hour=6,11|mood=sad",{1,"I didn't turn the radio on last night, first night I forgot",2,"That's alright",1,"What if last night was the night? What if that was when they said it?",2,"Then they'll say it again, nobody says a thing like that only once"}},
{"s2_c05_mutter_hens_017","any",1,"reg=civilian,family|tmp=seasoned|day=30,400|hour=5,9|mood=funny",{1,"Morning, girls, four eggs if you're feeling generous - three if you're not",1,"Clara, you were a good girl yesterday - Pearl, I saw what you did",1,"Two - well, everybody has a day"}},
{"s2_c05_layaway_bike_018","any",2,"reg=family|tmp=seasoned|day=30,160|mood=sad|world=building",{1,"Found the bike in the back of the hall closet - the one off layaway in June",2,"For Christmas",1,"It's already got a bow on it, you'd already bought the bow",2,"Give it to him now, don't wait on Christmas for anything anymore"}},
{"s2_c05_thermostat_hand_019","any",2,"reg=civilian,family|tmp=seasoned|day=15,400|mood=funny|world=building",{1,"I still reach for the thermostat every time I walk past that wall",2,"You still push it down to sixty-eight",1,"And you still come in behind me and push it back up",2,"Habit - mine's winning"}},
{"s2_c05_barn_cat_rat_020","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|mood=funny|world=building",{1,"Barn cat left a rat on the porch step, big as a squirrel",2,"That's a present",3,"Go out there and tell her thank you, go on",1,"I'm not thanking a cat",3,"She's the only one on this place bringing home meat this week"}},
{"s2_c05_hens_for_saw_021","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"The Creek sent a boy up with a note, two laying hens for our bow saw",2,"Our only bow saw",3,"Two laying hens is near an egg a day",2,"And that saw is every stick of firewood between now and March",1,"I'll write back, one hen, and we lend them the saw for a week"}},
{"s2_c05_pie_shop_022","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=90,250|mood=warm|world=building",{1,"When this is over, I'm opening a pie shop, right on Main",2,"You say that a lot",1,"Say what?",2,"When this is over, nobody's said it in this house since about October",1,"Should I quit saying it?",2,"No, say it some more, I've been missing it"}},
{"s2_c05_redbud_frost_cloth_023","any",3,"reg=civilian,family|tmp=seasoned|day=262,290|hour=17,22|mood=calm|world=snow",{1,"Stars are too clear, it's gonna frost tonight, and the tomato sets are already out",2,"Bedsheets over the rows, weighed down with bricks",3,"Those are the sheets off our beds",1,"Then we sleep under coats one night, and we eat tomatoes in July"}},
{"s2_c05_nobody_asks_024","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|hour=18,23|mood=grim|world=building",{1,"Found the Porter place today, all three of them, in the kitchen",2,"Pass the salt",3,"Here",1,"The table was set - four plates",2,"Eat your supper, Dan, tell it tomorrow in the daylight"}},
{"s2_c05_mutter_socks_on_stove_025","any",1,"reg=civilian,family|tmp=seasoned|day=180,240|hour=18,23|mood=calm|world=building",{1,"Boots by the stove, socks on the rail - gloves on the rail",1,"Not too close, last winter I melted a sole doing this",1,"Warm socks in the morning, that's the plan - that's plenty"}},
{"s2_c05_first_squash_blossom_026","any",2,"reg=civilian,family|tmp=seasoned|day=320,370|hour=5,10|mood=warm",{1,"Squash bloomed, big yellow flowers all down the row",2,"Last year this row was the Pruitts' side yard",1,"Last year I couldn't have told you a squash plant from a pumpkin",2,"You still can't, that's a pumpkin"}},
{"s2_routine_rain_barrel_001","any",2,"reg=civilian,family|tmp=seasoned|day=15,130",{1,"Barrel by the carport's full again, that storm last night did us a favor",2,"Did you put the screen back on it? I pulled two drowned mice out of there last week",1,"It's on - mostly on",2,"Then we're boiling it twice"}},
{"s2_routine_first_tomato_002","any",3,"reg=civilian,family|tmp=seasoned|day=20,100|hour=4,11|mood=warm",{1,"First ripe tomato came off the vine this morning - Brandywine, out of Mrs. Cole's seed packet",2,"You gonna share it or just hold it like a newborn?",1,"I'm cutting it in four, putting salt on it, and nobody talks while we eat",3,"I'll bring the salt, I been hiding the salt",2,"You been what?"}},
}
